// CreatedAtLTE applies the LTE predicate on the "created_at" field.
func CreatedAtLTE(v time.Time) predicate.KBAgentStep {
	return predicate.KBAgentStep(sql.FieldLTE(FieldCreatedAt, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.KBAgentStep) predicate.KBAgentStep {
	return predicate.KBAgentStep(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.KBAgentStep) predicate.KBAgentStep {
	return predicate.KBAgentStep(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.KBAgentStep) predicate.KBAgentStep {
	return predicate.KBAgentStep(sql.NotPredicates(p))
}
